import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    A = int(data[idx]); idx += 1
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    rows = []
    for i in range(N):
        row = [int(data[idx + j]) for j in range(M)]
        idx += M
        rows.append(row)  # rows[k] é a fila N-k (mais distante primeiro)

    def tem_run(row, A):
        cnt = 0
        for x in row:
            if x == 0:
                cnt += 1
                if cnt >= A:
                    return True
            else:
                cnt = 0
        return False

    # fila 1 é a última linha da entrada (mais próxima do palco)
    for fila in range(1, N + 1):
        row = rows[N - fila]
        if tem_run(row, A):
            print(fila)
            return
    print(-1)

main()
